=== StripeCheckoutModal ===
"use client";

import { useMemo } from "react";
import { loadStripe, type Stripe } from "@stripe/stripe-js";
import { EmbeddedCheckoutProvider, EmbeddedCheckout } from "@stripe/react-stripe-js";

/**
 * The ONE payment surface for the whole platform — Stripe Embedded Checkout rendered
 * in a modal ON our own page. Nobody is ever redirected to a Stripe-branded page: the
 * payment UI mounts inside this dialog (styled by our appearance settings), and on
 * completion Stripe navigates to the session's `return_url` — our own `/api/stripe/confirm`
 * route — which runs the SAME idempotent fulfilment the webhook does. So the audited
 * fulfilment engine is untouched; only the presentation changed from "redirect" to
 * "embedded modal".
 *
 * Usage: a flow's server action now returns `{ clientSecret, publishableKey }` (from a
 * Checkout Session created with `ui_mode: "embedded"`). The caller stores it in state and
 * renders `<StripeCheckoutModal ... onClose={...} />`.
 */

// loadStripe returns a singleton per key — cache so we don't re-init Stripe.js each open.
const stripeCache = new Map<string, Promise<Stripe | null>>();
function stripeFor(pk: string): Promise<Stripe | null> {
  let p = stripeCache.get(pk);
  if (!p) {
    p = loadStripe(pk);
    stripeCache.set(pk, p);
  }
  return p;
}

export function StripeCheckoutModal({
  clientSecret,
  publishableKey,
  onClose,
  title = "Checkout",
}: {
  clientSecret: string;
  publishableKey: string;
  onClose: () => void;
  title?: string;
}) {
  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);

  return (
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label={title}
    >
      <div className="relative my-auto w-full max-w-xl rounded-2xl border border-white/10 bg-navy-950 p-2 shadow-2xl">
        <div className="flex items-center justify-between px-3 pb-1 pt-2">
          <span className="text-sm font-semibold text-slate-200">{title}</span>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close checkout"
            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
          >
            ✕
          </button>
        </div>
        {/* Embedded Checkout renders inside this container — no navigation to Stripe. */}
        <div className="rounded-xl bg-white p-1">
          <EmbeddedCheckoutProvider stripe={stripePromise} options={{ clientSecret }}>
            <EmbeddedCheckout />
          </EmbeddedCheckoutProvider>
        </div>
      </div>
    </div>
  );
}
=== api/stripe/checkout route ===
import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { stripe, stripeConfigured, stripePublishableKey, EMBEDDED_UI_MODE, EMBEDDED_REQUEST_OPTS } from "@/lib/stripe";
import { ensureStripeCustomer } from "@/lib/stripe-cards";
import { getSettingInt } from "@/lib/settings";

/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
const COUPON_COOKIE = "nxeon_coupon";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (Math.round(dollars * 100) < minTopup) {
    return NextResponse.json(
      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
      { status: 400 },
    );
  }

  // A promo code must never be silently dropped at the moment money moves.
  //
  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
  // reader is the demo gateway in `topUp`. This route charges the card and
  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
  // simply cannot be added here — and Stripe's own `discounts` /
  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
  // customer exactly where they started. So a cookie surviving into this path
  // (e.g. Stripe was configured after the code was accepted) would mean paying
  // full price with a code the UI said was applied — the audit's finding #8.
  //
  // Refuse, say why, and clear the cookie in the same response so the immediate
  // retry succeeds. Nothing has been charged at this point: no session exists yet.
  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
  if (staleCoupon) {
    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
    const res = NextResponse.json(
      {
        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
      },
      { status: 400 },
    );
    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
    return res;
  }

  const base = process.env.APP_URL ?? "http://localhost:3000";
  // Attach the top-up to a Stripe CUSTOMER and save the card so a customer who only
  // ever tops up their wallet still gets a chargeable card on file for off-session
  // renewals. `customer` replaces `customer_email` (Stripe rejects a session with
  // both), and setup_future_usage records the payment method against the customer.
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer: customerId,
    payment_intent_data: { setup_future_usage: "off_session" },
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Nxeon wallet credit" },
          unit_amount: Math.round(dollars * 100),
        },
        quantity: 1,
      },
    ],
    metadata: { nxeonUserId: user.id },
    // Embedded: the card form mounts in a modal on OUR billing page. On success
    // Stripe navigates the top window to return_url — the same confirm route that
    // credits the wallet — so the fulfilment round-trip is byte-for-byte unchanged.
    // embedded_page + pinned API version — see EMBEDDED_UI_MODE doc in lib/stripe.ts.
    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return NextResponse.json(
    session.client_secret
      ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
      : { error: "Stripe didn't return a session. Please try again." },
    session.client_secret ? undefined : { status: 502 },
  );
}

