275	/**
276	 * Shared appearance so the Payment Element reads as part of THIS page, not a
277	 * visiting Stripe widget — dark surfaces matching the wizard's card chrome.
278	 *
279	 * `fontFamily: "inherit"` looked like it would pick up the page's own Geist
280	 * typeface, but Elements render inside a cross-origin js.stripe.com iframe —
281	 * "inherit" resolves against THAT document, which has no ancestor font-family
282	 * of its own, so it fell through to the browser default serif (a real bug: it
283	 * rendered as a dated Times New Roman look, not Geist). `STRIPE_FONTS` loads
284	 * the actual typeface into the iframe via Stripe's documented `cssSrc` option
285	 * (the one way to add a custom font — same-origin @font-face rules on the
286	 * parent page are invisible to the iframe), and `fontFamily` below names it.
287	 */
288	const STRIPE_FONTS = [{ cssSrc: "https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap" }];
289	const STRIPE_APPEARANCE = {
290	  theme: "night" as const,
291	  variables: {
292	    colorPrimary: "#7c5cff",
293	    colorBackground: "#0b0f1f",
294	    colorText: "#e2e8f0",
295	    colorDanger: "#f87171",
296	    fontFamily: "'Geist', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
297	    borderRadius: "10px",
298	    spacingUnit: "4px",
299	  },
300	  rules: {
301	    ".Input": { border: "1px solid rgba(255,255,255,0.09)", boxShadow: "none" },
302	    ".Input:focus": { border: "1px solid rgba(124,92,255,0.6)", boxShadow: "0 0 0 1px rgba(124,92,255,0.4)" },
303	    ".Label": { color: "#94a3b8" },
304	  },
305	};
