307	/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckout()` is valid. */
308	function CardAndWalletsBlock({
309	  selected,
310	  onSelectCard,
311	  saveCard,
312	  onToggleSaveCard,
313	  totalDueCents,
314	}: {
315	  selected: Method;
316	  onSelectCard: () => void;
317	  saveCard: boolean;
318	  onToggleSaveCard: (v: boolean) => void;
319	  totalDueCents: number;
320	}) {
321	  // useCheckoutElements() (not the deprecated useCheckout()) returns a
322	  // discriminated union — {type:"loading"} while the Elements SDK is still
323	  // initializing, {type:"error"} if it failed, {type:"success", checkout}
324	  // once ready. `checkoutActions` is that inner `checkout` object, undefined
325	  // until "success" — every confirm() call below is guarded on it existing,
326	  // so a click during the loading window can't throw.
327	  const checkoutState = useCheckoutElements();
328	  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
329	  const [confirming, setConfirming] = useState(false);
330	  const [error, setError] = useState<string | null>(null);
331	  const [name, setName] = useState("");
332	  const [expressPayAvailable, setExpressPayAvailable] = useState(false);
333	
334	  async function payWithCard() {
335	    if (!checkoutActions) return;
336	    setError(null);
337	    setConfirming(true);
338	    try {
339	      const result = await checkoutActions.confirm({ savePaymentMethod: saveCard });
340	      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
341	      // On success Stripe navigates the browser to the session's return_url
342	      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
343	      // payment on this platform. Nothing else to do here.
344	    } catch {
345	      setError("Something went wrong confirming your payment. Please try again.");
346	    } finally {
347	      setConfirming(false);
348	    }
349	  }
350	
351	  return (
352	    <>
353	      <MethodRow
354	        id="card"
355	        selected={selected === "card"}
356	        onSelect={onSelectCard}
357	        icon={<CardIcon />}
358	        title="Credit / Debit Card"
359	        subtitle="Visa, Mastercard, American Express and more"
360	      >
361	        <div className="space-y-4">
362	          <div>
363	            <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
364	              <LockIcon /> Card details
365	            </label>
366	            <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
367	              <PaymentElement
368	                options={{
369	                  layout: "tabs",
370	                  fields: { billingDetails: { name: "never" } },
371	                  paymentMethodOrder: ["card"],
372	                }}
373	              />
374	            </div>
375	          </div>
376	          <div>
377	            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
378	            <input
379	              type="text"
380	              value={name}
381	              onChange={(e) => setName(e.target.value)}
382	              placeholder="Name on card"
383	              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
384	            />
385	          </div>
386	          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
387	            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
388	            <span className="text-xs text-slate-400">
389	              <span className="font-medium text-slate-300">Save card for faster checkout</span>
390	              <br />
391	              Nxeon plans renew automatically, so your card is always saved securely with Stripe for your next billing cycle — this isn&apos;t optional for a subscription product, which is why the box is checked.
392	            </span>
393	          </label>
394	          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
395	          <button
396	            type="button"
397	            onClick={payWithCard}
398	            disabled={confirming || !checkoutActions?.canConfirm}
399	            className="btn-deploy w-full py-3 text-sm"
400	          >
401	            <LockIcon className="h-4 w-4" />
402	            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
403	            {!confirming && <span className="dep-arrow">→</span>}
404	          </button>
405	        </div>
406	      </MethodRow>
407	
408	      {/*
409	        ONE ExpressCheckoutElement, always mounted, showing whichever wallets
410	        the browser/device actually supports (Stripe renders them side by
411	        side itself). This used to be TWO separate elements — one per wallet,
412	        each shown only when its own MethodRow was the "selected" radio
413	        option — which looked static (nothing to click until you clicked the
414	        row first) and, worse, having both mount at once (needed to fix the
415	        static look) throws Stripe's own "cannot create multiple instances of
416	        the Express Checkout Element" error. A single instance covering both
417	        wallets is Stripe's actual supported shape for this. Hidden entirely
418	        (via onReady's availablePaymentMethods) when NEITHER wallet is
419	        available on this browser/device/card.
420	      */}
421	      {/* Always mounted (never conditionally unmounted) so onReady gets a
422	          chance to fire at all — only its VISIBILITY is gated on the result,
423	          via a CSS class rather than removing it from the tree. */}
424	      <div className={expressPayAvailable ? "rounded-xl border border-white/[0.07] bg-white/[0.02] p-4" : "hidden"}>
425	          <p className="mb-3 text-xs font-medium text-slate-400">Express checkout</p>
426	          <ExpressCheckoutElement
427	            options={{
428	              // The /checkout subpath's ExpressCheckoutElementOptions requires
429	              // every key present (unlike the main package's), even though
430	              // Stripe treats undefined the same as omitted for each of these.
431	              buttonHeight: undefined,
432	              buttonTheme: undefined,
433	              buttonType: undefined,
434	              layout: undefined,
435	              paymentMethodOrder: undefined,
436	              paymentMethods: { googlePay: "auto", applePay: "auto", link: "never", paypal: "never", amazonPay: "never" },
437	            }}
438	            onReady={(e) =>
439	              setExpressPayAvailable(!!(e.availablePaymentMethods?.googlePay || e.availablePaymentMethods?.applePay))
440	            }
441	            // The Custom Checkout version of this element does not expose
442	            // onClick (Stripe's SDK owns opening the OS payment sheet
443	            // entirely).
444	            onConfirm={async (event) => {
445	              if (!checkoutActions) return;
446	              setError(null);
447	              const result = await checkoutActions.confirm({ expressCheckoutConfirmEvent: event });
448	              if (result.type === "error") setError(result.error.message ?? "Payment failed.");
449	            }}
450	          />
451	      </div>
452	    </>
453	  );
454	}
