// Prisma wallet-balance check for the audit account, run against staging's DB.
import { PrismaClient } from "/opt/nxeon-staging/node_modules/@prisma/client/index.js";

const db = new PrismaClient();
const user = await db.user.findUnique({
  where: { email: "claude-audit-2026@nxeon.test" },
  select: { id: true, email: true, balanceCents: true },
});
console.log(JSON.stringify(user));
await db.$disconnect();

import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";
import { mkdirSync } from "fs";

const BASE = "https://staging.nxeon.cloud";
const shots = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
mkdirSync(shots, { recursive: true });

const consoleErrors = [];
const pageErrors = [];

const browser = await chromium.launch();
const context = await browser.newContext({ bypassCSP: true });
const page = await context.newPage();

page.on("console", (msg) => { if (msg.type() === "error") consoleErrors.push(msg.text()); });
page.on("pageerror", (err) => pageErrors.push(String(err)));

async function shot(name) {
  await page.screenshot({ path: `${shots}/${name}.png`, fullPage: true });
}

console.log("== login ==");
await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
await page.fill('input[name="email"]', "claude-audit-2026@nxeon.test");
await page.fill('input[name="password"]', "AuditPass123!");
await page.click("button.btn-primary", { noWaitAfter: true });
await page.waitForURL((u) => !u.pathname.startsWith("/login"), { timeout: 20000 }).catch((e) => console.log("waitForURL:", e.message));
await page.waitForLoadState("networkidle").catch(() => {});
console.log("post-login url:", page.url());

console.log("== billing page ==");
await page.goto(`${BASE}/dashboard/billing`, { waitUntil: "networkidle" });
const acceptCookies = page.locator('button:has-text("Got it")').first();
if (await acceptCookies.count()) { await acceptCookies.click().catch(() => {}); await page.waitForTimeout(300); }
await shot("b01-billing-page");

console.log("== select $25 preset and click Add funds ==");
const preset25 = page.locator('button:has-text("$25")').first();
if (await preset25.count()) { await preset25.click(); await page.waitForTimeout(200); }
await shot("b02-amount-selected");

const addFundsBtn = page.locator('button:has-text("Add funds")').first();
console.log("Add funds button count:", await addFundsBtn.count());
await addFundsBtn.click();
await page.waitForTimeout(1500);
await shot("b03-modal-opened");

// Basic overlap/sanity check: modal dialog bounding box vs viewport, and
// whether the amount text / Stripe payment element are both visible without
// clipping.
const dialog = page.locator('[role="dialog"][aria-label="Add funds"]');
console.log("dialog count:", await dialog.count());
if (await dialog.count()) {
  const box = await dialog.locator("> div").first().boundingBox();
  console.log("modal card boundingBox:", JSON.stringify(box));
  const headerText = await dialog.locator("p.text-xs.text-slate-500").first().innerText().catch(() => "?");
  console.log("modal subtitle text:", headerText);
}

const stripeFrameCount = await page.locator('iframe[name*="stripe" i], iframe[src*="stripe" i]').count();
console.log("stripe iframes present:", stripeFrameCount);

console.log("\n== filling test card ==");
const cardFrameHandle = page.frames().find((f) => /elements-inner-payment-[a-f0-9]/.test(f.url()) && !/elements-inner-payment-api/.test(f.url()));
const paymentFrame = cardFrameHandle
  ? page.frameLocator(`iframe[name="${cardFrameHandle.name()}"]`)
  : page.frameLocator('iframe[title="Secure payment input frame"]').first();
try {
  await paymentFrame.locator('input[name="number"]').fill("4242424242424242", { timeout: 8000 });
  await paymentFrame.locator('input[name="expiry"]').fill("12/34");
  await paymentFrame.locator('input[name="cvc"]').fill("123");
  console.log("card fields filled");
  await page.keyboard.press("Escape").catch(() => {});
} catch (e) {
  console.log("card fill error:", e.message);
  const html = await paymentFrame.locator("body").innerHTML().catch(() => "?");
  console.log("payment frame body (first 1000 chars):", html.slice(0, 1000));
}
await shot("b04-card-filled");

const payBtn = page.locator('button:has-text("Pay Securely")').first();
console.log("Pay button count:", await payBtn.count());
if (await payBtn.count()) {
  const disabled = await payBtn.isDisabled().catch(() => true);
  console.log("Pay button disabled?", disabled);
  if (!disabled) {
    await payBtn.click();
    await page.waitForTimeout(9000);
    await shot("b05-after-pay-click");
    console.log("url after pay click:", page.url());
    const successBanner = await page.locator("text=Payment received").count();
    console.log("success banner present:", successBanner > 0);
  }
}

await browser.close();

console.log("\n=== CONSOLE ERRORS ===");
console.log(consoleErrors.slice(0, 40).join("\n") || "(none)");
console.log("\n=== PAGE ERRORS ===");
console.log(pageErrors.slice(0, 20).join("\n") || "(none)");

